def _build_children() -> dict[str, list[str]]:
    children: dict[str, list[str]] = {}
    for code, (_, parent) in THEMA_CODES.items():
        children.setdefault(parent, []).append(code)
    for codes_list in children.values():
        codes_list.sort(key=lambda c: THEMA_CODES[c][0])
    return children


THEMA_CHILDREN: dict[str, list[str]] = _build_children()


def thema_children(parent_code: str) -> list[tuple[str, str]]:
    """(code, libellé) triés alphabétiquement par libellé — parent_code="" retourne
    les catégories racines."""
    return [(c, THEMA_CODES[c][0]) for c in THEMA_CHILDREN.get(parent_code, [])]


def thema_label(code: str) -> str:
    return THEMA_CODES[code][0] if code in THEMA_CODES else code


def thema_parent_chain(code: str) -> list[str]:
    """[racine, ..., code] — pour pré-sélectionner les menus en cascade au chargement
    d'un code déjà connu (ui/generate_panel.py::_ThemaRow.set_code)."""
    chain: list[str] = []
    while code:
        chain.append(code)
        code = THEMA_CODES.get(code, ("", ""))[1]
    return list(reversed(chain))
